<?php require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../includes/functions.php';if(empty($_SESSION['admin_id'])){header('Location: login.php');exit;}$pageTitle='Admin dashboard';$sales=$pdo->query("SELECT COALESCE(SUM(total_amount),0) FROM orders WHERE order_status<>'Cancelled'")->fetchColumn();$pending=$pdo->query("SELECT COUNT(*) FROM orders WHERE order_status='Pending'")->fetchColumn();$empty=$pdo->query('SELECT COUNT(*) FROM products WHERE stock_quantity=0')->fetchColumn();$orders=$pdo->query('SELECT order_code,total_amount,order_status,created_at FROM orders ORDER BY id DESC LIMIT 10')->fetchAll();require __DIR__.'/../includes/header.php'; ?><div class="container section-space"><div class="d-flex justify-content-between mb-4"><h1 class="h2">Admin dashboard</h1><a href="logout.php" class="btn btn-outline-dark btn-sm">Log out</a></div><div class="row g-3 mb-4"><?php foreach(['Recorded demo sales'=>money($sales),'Pending orders'=>$pending,'Out of stock'=>$empty] as $label=>$value): ?><div class="col-md-4"><div class="panel"><div class="meta"><?=$label?></div><div class="h3 mt-2"><?=$value?></div></div></div><?php endforeach; ?></div><div class="d-flex justify-content-between"><h2 class="h5">Recent orders</h2><a href="add-product.php" class="btn btn-dark btn-sm">Add product</a></div><div class="table-responsive panel mt-3"><table class="table"><thead><tr><th>Order</th><th>Date</th><th>Status</th><th class="text-end">Total</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><?=e($o['order_code'])?></td><td><?=e($o['created_at'])?></td><td><?=e($o['order_status'])?></td><td class="text-end"><?=money($o['total_amount'])?></td></tr><?php endforeach; ?><?php if(!$orders): ?><tr><td colspan="4">No orders yet.</td></tr><?php endif; ?></tbody></table></div></div><?php require __DIR__.'/../includes/footer.php'; ?>